-- OPTIONAL COURSE SEED: current schema must already be installed. No DDL.
-- Reconstructed from Git HEAD 6ab81e9 course source and importer; not the original executed production file.
-- Set odu.course_owner_id and odu.course_owner_email to this installation's verified Auth owner.
-- Then set the explicit confirmation below and run the whole file in the SAME session.
-- Imports PRIVATE/pending_review; publication uses normal Settings and Admin approval.
-- AI 101 optional import, originally generated from the retired reviewed course JSON.
-- Review before execution. Verify the target project before running. This file does not create Auth users.
-- In the same target DB session first run:
-- set odu.allow_production_seed = 'ai101-production-approved';
begin;
set local statement_timeout = '15s';
set local lock_timeout = '5s';
do $ai101_seed$
declare
 v_owner uuid := nullif(current_setting('odu.course_owner_id',true),'')::uuid;
 v_path uuid := 'ab832bcc-b30c-59cf-a3c2-fecf069bd475';
 v_plan jsonb := '[{"id":"1a5b4426-6ded-5954-ab97-762d4ba9d5db","title":"What Is Artificial Intelligence?","goal":"Understand what AI is and how AI, machine learning, deep learning, and generative AI relate to one another.","days":[{"id":"2abef259-4f68-52dd-94d8-538ea628406b","dayLabel":"Day 1","title":"What Is Artificial Intelligence?","hours":"1.00","contentMarkdown":"**Objective:** Understand what AI is and how AI, machine learning, deep learning, and generative AI relate to one another.\n\n## Understand\n\nArtificial intelligence is the broader field of building computer systems capable of performing tasks associated with human intelligence, such as recognizing patterns, understanding language, making predictions, and planning actions.\n\nMachine learning is a subset of AI in which models learn patterns from data rather than relying entirely on manually programmed rules.\n\nDeep learning is a subset of machine learning that uses neural networks containing multiple layers.\n\nGenerative AI creates new content, such as text, images, audio, code, and video.\n\nHere are everyday examples:\n\n- Spam filters identify unwanted emails.\n- Recommendation engines suggest videos and products.\n- Fraud detection identifies unusual transactions.\n- Voice assistants process spoken commands.\n- Generative AI assistants create and transform content.\n\nOrdinary automation is not necessarily AI: a fixed rule that sends a reminder is automation even if it never learns from data. Not every AI application uses a large language model; a spam classifier can predict a category without generating a conversation.\n\n## Watch\n\n- [John Savill — Artificial Intelligence and Machine Learning for Everyone](https://www.youtube.com/watch?v=C7Iu2lcoAQ4)\n\n## Read\n\n- [Microsoft Learn — Introduction to AI Concepts](https://learn.microsoft.com/en-us/training/modules/get-started-ai-fundamentals/)\n\n## Practice activity\n\n**Spot AI Around You**\n\nIdentify five applications that use AI.\n\nFor each, describe:\n- What problem it solves.\n- What input it processes.\n- What output it produces.\n- Whether it is predictive, generative, or another AI application.\n\n## Expected outcome\n\nYou can distinguish AI, ML, deep learning, and generative AI and identify practical use cases.\n\nAfter working through the activity, mark the completion item for this day. Keep your reflection in Personal Notes. Completion is self-reported participation, not verified mastery.","items":[{"id":"31858ba3-a772-5cd4-b68e-7d35e1280eaf","title":"Complete Day 1: What Is Artificial Intelligence?","url":"https://learn.microsoft.com/en-us/training/modules/get-started-ai-fundamentals/","tag":"hands"}]}]},{"id":"a5b9683b-d649-54bf-9b53-0bf6b0b2b3ae","title":"How Do Machines Learn?","goal":"Understand how data is used to train machine learning models and how models make predictions.","days":[{"id":"4974219b-bff7-50ae-9cf0-1ef15dd348d6","dayLabel":"Day 2","title":"How Do Machines Learn?","hours":"1.08","contentMarkdown":"**Objective:** Understand how data is used to train machine learning models and how models make predictions.\n\n## Understand\n\nTraditional software follows explicitly programmed instructions.\n\nMachine learning uses algorithms to identify patterns from data.\n\nKey ideas to recognize:\n\n- Training data\n- Features and labels\n- Supervised learning\n- Unsupervised learning\n- Training\n- Inference\n- Neural networks\n- Model evaluation\n- Generalization\n- Overfitting\n\nExample:\n\nA spam classifier can learn from labeled emails and predict whether a new message is spam.\n\nTraining is the process of learning from examples.\n\nInference is using a trained model to process new inputs.\n\nGeneralization means performing well on examples not seen during training.\n\nOverfitting happens when a model performs well on training examples but poorly on new data.\n\n**Features** are the information a model uses, such as words in an email. A **label** is the answer supplied in a training example, such as spam or not spam. **Supervised learning** uses examples with labels. **Unsupervised learning** looks for structure, such as groups of similar examples, without those answer labels.\n\nA **neural network** combines connected layers of calculations. Training adjusts its internal weights to reduce errors on examples. **Evaluation** checks performance on examples kept separate from training. A useful test includes unfamiliar cases, not just copies of the examples the model has already seen.\n\n## Watch\n\n- [3Blue1Brown — But What Is a Neural Network?](https://www.youtube.com/watch?v=aircAruvnKk)\n\n## Read\n\n- [Google — Introduction to Machine Learning](https://developers.google.com/machine-learning/intro-to-ml)\n\n## Practice\n\n- [Google Teachable Machine](https://teachablemachine.withgoogle.com/)\n\n## Practice activity\n\n**Train Your First Model**\n\n1. Open Teachable Machine.\n2. Create two image categories.\n3. Add examples for each.\n4. Train the classifier.\n5. Test new examples.\n6. Observe correct and incorrect predictions.\n\nUse the written alternative below if the tool is unavailable.\n\n### Written alternative\n\nIf Teachable Machine is unavailable, draw two image categories and describe five training examples for each. Reserve two different examples for testing. Predict where the classifier might fail (lighting, backgrounds, or unfamiliar objects), and explain how you would improve the training data. No webcam or personal images are required.\n\n## Expected outcome\n\nYou understand how data influences model training and why models must work on unfamiliar examples.\n\nAfter working through the activity, mark the completion item for this day. Keep your reflection in Personal Notes. Completion is self-reported participation, not verified mastery.","items":[{"id":"6be99f81-28a4-59ae-87db-57f8b94572b1","title":"Complete Day 2: How Do Machines Learn?","url":"https://developers.google.com/machine-learning/intro-to-ml","tag":"hands"}]}]},{"id":"4ee4578d-93c3-5e2b-bfd2-3910ccb4f7f9","title":"Generative AI and Large Language Models","goal":"Understand generative AI, LLMs, tokens, context, and hallucinations.","days":[{"id":"4c731427-1a3f-5593-9b8b-b6630745e56c","dayLabel":"Day 3","title":"Generative AI and Large Language Models","hours":"1.00","contentMarkdown":"**Objective:** Understand generative AI, LLMs, tokens, context, and hallucinations.\n\n## Understand\n\nLarge language models are trained on extensive data to learn patterns in sequences of tokens.\n\nDuring generation, an LLM predicts successive tokens based on the context available.\n\nKey terms:\n\n- Generative AI\n- Large language models\n- Tokens\n- Context windows\n- Transformers\n- Next-token prediction\n- Hallucinations\n- Factual reliability\n\nA token is a unit of text used during processing.\n\nThe context window limits the information the model can consider in a given interaction.\n\nTransformers are a neural network architecture widely used in modern LLMs.\n\nHallucinations occur when models generate inaccurate or unsupported information.\n\nPractical applications include:\n- Summarization\n- Translation\n- Document analysis\n- Writing assistance\n- Code generation\n- Personalized tutoring\n\n**Next-token prediction** means choosing another token based on the sequence so far, then repeating that process. A fluent answer can still be wrong: generating a plausible sequence is not the same as checking a fact. The context window is a limit on the information available in that interaction, not a guarantee of permanent memory.\n\nFor important factual claims, compare the answer with an independent, trustworthy source. Ask which claims are supported, what information is missing, and whether the answer expresses uncertainty. An AI tutor can help you practice, but you remain responsible for checking its explanations.\n\n## Watch\n\n- [3Blue1Brown — Large Language Models Explained Briefly](https://www.youtube.com/watch?v=LPZh9BOjkQs)\n\n## Read\n\n- [Microsoft Learn — Introduction to Generative AI and Agents](https://learn.microsoft.com/en-us/training/modules/fundamentals-generative-ai/)\n\n## Practice activity\n\n**Explore an AI Assistant**\n\nAsk an AI assistant to:\n\n1. Explain a complex topic in simple language.\n2. Summarize a paragraph.\n3. Generate a study plan.\n\nCompare the outputs and independently check at least one factual claim.\n\nThis is a practical reflection activity, not an ODU assessment.\n\nIf an AI assistant is unavailable, write the prompts and describe what a useful response should contain. Compare example responses with a peer or revisit the activity when a free assistant is available. Do not use private or sensitive information.\n\n## Expected outcome\n\nYou understand how LLMs generate language and recognizes their limitations.\n\nAfter working through the activity, mark the completion item for this day. Keep your reflection in Personal Notes. Completion is self-reported participation, not verified mastery.","items":[{"id":"cfdebef2-9785-5604-b394-ce96e3354a7a","title":"Complete Day 3: Generative AI and Large Language Models","url":"https://learn.microsoft.com/en-us/training/modules/fundamentals-generative-ai/","tag":"hands"}]}]},{"id":"908d6bbe-5f79-5297-bdda-01cb92568b74","title":"Prompt Engineering Fundamentals","goal":"Learn to write clear and structured prompts to improve AI responses.","days":[{"id":"80f6d0dd-58bc-54cd-b914-fa2bdef02da4","dayLabel":"Day 4","title":"Prompt Engineering Fundamentals","hours":"1.00","contentMarkdown":"**Objective:** Learn to write clear and structured prompts to improve AI responses.\n\n## Understand\n\nA prompt is input that instructs an AI system to perform a task.\n\nA useful prompt typically includes:\n\n1. Task or objective.\n2. Relevant context.\n3. Constraints.\n4. Desired output format.\n5. Examples where helpful.\n\nWeak prompt:\n\n\"Teach me Python.\"\n\nImproved prompt:\n\n\"I am a complete beginner. Create a seven-day Python learning plan that takes 30 minutes per day. Include simple explanations, practical examples, and one daily exercise. Present it as a table.\"\n\nThe improved prompt identifies the learner, sets a seven-day scope and a daily time limit, asks for examples and exercises, and specifies a table. These details give the assistant a clearer target and make its response easier to evaluate. More detail helps only when it is relevant; extra words alone do not guarantee a correct answer.\n\nPrompt engineering is iterative: test, evaluate, and improve instructions.\n\n## Read\n\n- [Learn Prompting — Introduction](https://learnprompting.org/docs/introduction)\n- [Microsoft Learn — Get Started with AI](https://learn.microsoft.com/en-us/training/modules/get-started-with-ai/)\n\n## Practice activity\n\n**Improve Your Prompts**\n\nChoose three vague prompts.\n\nRewrite them with:\n- Clear task\n- Context\n- Constraints\n- Output format\n\nCompare the resulting outputs.\n\nIf an AI assistant is unavailable, write the prompts and describe what a useful response should contain. Compare example responses with a peer or revisit the activity when a free assistant is available. Do not use private or sensitive information.\n\n## Expected outcome\n\nYou can prepare effective prompts for common practical tasks.\n\nAfter working through the activity, mark the completion item for this day. Keep your reflection in Personal Notes. Completion is self-reported participation, not verified mastery.","items":[{"id":"11926a4b-996c-5d84-8d75-eca4d0d77102","title":"Complete Day 4: Prompt Engineering Fundamentals","url":"https://learnprompting.org/docs/introduction","tag":"hands"}]}]},{"id":"bd55e4f9-0c1a-51f6-8e96-993ee02898b0","title":"AI in the Real World and Responsible AI","goal":"Explore important AI applications and understand ethical and practical considerations.","days":[{"id":"e3763245-16d3-5d14-ac2a-d1c44c100cc8","dayLabel":"Day 5","title":"AI in the Real World and Responsible AI","hours":"1.08","contentMarkdown":"**Objective:** Explore important AI applications and understand ethical and practical considerations.\n\n## Understand\n\nAI can improve existing workflows or make new applications possible.\n\nUse cases:\n\n**Education:**\nPersonalized tutoring, study recommendations, and content summarization.\n\n**Healthcare:**\nMedical image analysis and decision-support systems with professional oversight.\n\n**Agriculture:**\nCrop-health monitoring and disease detection.\n\n**Finance:**\nFraud detection and risk monitoring.\n\n**Telecommunications:**\nNetwork anomaly detection and predictive maintenance.\n\n**Software Engineering:**\nCoding assistance, test generation, and documentation.\n\nResponsible AI checks:\n\n- Accuracy and reliability\n- Bias and fairness\n- Privacy\n- Security\n- Transparency\n- Human oversight\n- Appropriate use-case selection\n\nSuccessful AI solutions start with a real problem and measurable outcomes.\n\nCheck **accuracy** with representative examples and **fairness** across the people or situations the system may affect. Protect **privacy** by avoiding unnecessary personal information. Consider **security** before sharing data or connecting tools. Explain the system''s **limitations** and keep a person responsible for reviewing important decisions.\n\nFor example, a study-summary assistant might save time, but it can omit an important idea or invent a detail. A sensible success criterion is a useful summary with key claims checked against the source, rather than simply producing more text.\n\n## Read\n\n- [Google — Introduction to ML Problem Framing](https://developers.google.com/machine-learning/problem-framing)\n- [Microsoft Learn — Prepare to Use Generative AI at Work](https://learn.microsoft.com/en-us/training/modules/what-generative-ai/)\n\n## Practice activity\n\n**Identify an AI Opportunity**\n\nChoose a problem and document:\n\n1. Problem description.\n2. Intended users.\n3. Proposed AI assistance.\n4. Input data.\n5. Expected benefits.\n6. Risks and limitations.\n7. Success criteria.\n\n## Expected outcome\n\nYou can identify a practical AI use case and describe its value and risks.\n\nAfter working through the activity, mark the completion item for this day. Keep your reflection in Personal Notes. Completion is self-reported participation, not verified mastery.","items":[{"id":"a0886906-cff2-5ae9-95a9-5cc69735f517","title":"Complete Day 5: AI in the Real World and Responsible AI","url":"https://developers.google.com/machine-learning/problem-framing","tag":"hands"}]}]},{"id":"2a1342a2-b869-54db-b25b-207736872aef","title":"How AI-Powered Applications Are Built","goal":"Understand how software applications interact with AI models and external knowledge sources.","days":[{"id":"737568ff-ccb8-5f9e-904e-5cb9164ce57b","dayLabel":"Day 6","title":"How AI-Powered Applications Are Built","hours":"1.17","contentMarkdown":"**Objective:** Understand how software applications interact with AI models and external knowledge sources.\n\n## Understand\n\nA simplified application flow:\n\nUser → Frontend → Backend → AI Model API → Response Processing → User\n\nFrontend:\nCaptures user inputs and displays results.\n\nBackend:\nPrepares requests, enforces business rules, protects credentials, and calls the model.\n\nAI Model API:\nProcesses input and generates a response.\n\nResponse Processing:\nValidates outputs and formats results.\n\nThree common patterns:\n\n**Chatbot:**\nUses a language model to generate responses from user input and supplied context.\n\n**Retrieval-Augmented Generation (RAG):**\nRetrieves relevant information from documents or other sources and provides that context to the model.\n\n**AI Agent:**\nCombines models with tools and workflow logic to perform multi-step tasks.\n\nRAG often works without retraining the underlying model: retrieval supplies relevant context when the request is made. It does not guarantee that the answer is accurate, so source selection and checking still matter.\n\nKeep API keys on the backend rather than exposing them in browser code. Check that inputs are appropriate before sending them to a provider, and validate responses before displaying or acting on them. Never paste secrets or private learning records into a public assistant.\n\nIn a study assistant, the frontend collects a topic, the backend prepares a request, and the model returns a draft explanation. Response handling can check that the answer has the requested sections and show a reminder to verify factual claims. A RAG version can retrieve relevant notes first. An agent adds tools and workflow steps; those actions need clear limits and human oversight. These are concepts for your design, not AI services currently provided by ODU.\n\n## Read\n\n- [Microsoft Learn — AI Concepts for Developers](https://learn.microsoft.com/en-us/training/paths/ai-concepts/)\n\n## References — optional developer extension\n\n- [Google Gemini API — Getting Started](https://ai.google.dev/gemini-api/docs/get-started) — Optional\n- [OpenAI API — Quickstart](https://developers.openai.com/api/docs/quickstart) — Optional\n\n## Practice activity\n\n**Design an AI Study Assistant**\n\nCreate a simple diagram or written description that shows:\n\n1. User question.\n2. Frontend.\n3. Backend.\n4. Model API.\n5. Response handling.\n6. Answer displayed.\n\nOptional: Add document retrieval to the design.\n\n## Expected outcome\n\nYou can explain the key components of an AI-powered application.\n\nAfter working through the activity, mark the completion item for this day. Keep your reflection in Personal Notes. Completion is self-reported participation, not verified mastery.","items":[{"id":"55731943-4794-53e8-800f-817d524cc035","title":"Complete Day 6: How AI-Powered Applications Are Built","url":"https://learn.microsoft.com/en-us/training/paths/ai-concepts/","tag":"hands"}]}]},{"id":"e5405185-69c5-51e1-a5fe-3a22b6f72e6a","title":"Build Your First AI Solution","goal":"Apply the concepts learned during the week to create a practical AI assistant prototype.","days":[{"id":"b07e772a-bd31-57c9-b1d7-74c7a5e69291","dayLabel":"Day 7","title":"Build Your First AI Solution","hours":"1.50","contentMarkdown":"**Objective:** Apply the concepts learned during the week to create a practical AI assistant prototype.\n\n## Understand\n\n## My AI Study Buddy\n\nCreate a prompt-based AI assistant that can:\n\n- Accept a learning topic.\n- Accept the learner''s experience level.\n- Explain the topic.\n- Provide examples.\n- Generate practice questions.\n- Give feedback to the user.\n\n## Beginner implementation\n\nNo programming required.\n\nUse an AI assistant and create a reusable prompt.\n\nExample:\n\n\"You are an educational tutor helping beginners learn unfamiliar topics.\n\nAsk the learner for the topic and their experience level.\n\nExplain the topic in simple language.\n\nProvide two practical examples.\n\nGenerate five practice questions.\n\nAsk the learner to answer before revealing the correct answers.\n\nProvide explanations and suggest what to study next.\n\nAvoid inventing facts and clearly identify uncertainty.\"\n\nThe practice questions here are generated in an external AI assistant as part of the learner''s own project, not through an ODU assessment module.\n\n## Optional developer extension\n\nDevelop a small frontend application connected to an AI model API.\n\nThis extension is optional. The reusable prompt is enough for required course completion; you do not need programming or a paid API.\n\n## Practice activity\n\nBuild and test the prompt-based study buddy described above.\n\n- A working prompt-based prototype.\n- Three test scenarios.\n- Example AI responses.\n- A short reflection describing strengths, limitations, and improvements.\n\nIf you cannot access a free AI assistant, prepare the reusable prompt and walk through the three test scenarios on paper as a design prototype. Running a model or paying for an API is not required. An optional coded extension is not part of required completion.\n\n## Expected outcome\n\nYou have built a simple AI-powered solution and understands how it works.\n\nAfter working through the activity, mark the completion item for this day. Keep your reflection in Personal Notes. Completion is self-reported participation, not verified mastery.","items":[{"id":"1466783c-2235-5496-9c8b-8373a8cb6224","title":"Complete Day 7: Build Your First AI Solution","url":"https://learn.microsoft.com/en-us/training/paths/ai-fluency/","tag":"hands"}]}]}]'::jsonb;
 v_phase jsonb; v_day jsonb; v_item jsonb;
 v_creator uuid;
 v_revision integer;
 v_limit integer;
 v_current jsonb;
begin
 if current_setting('odu.allow_production_seed',true) is distinct from 'ai101-production-approved' then
  raise exception 'Production import requires explicit odu.allow_production_seed confirmation';
 end if;
 if not exists(select 1 from auth.users where id=v_owner and lower(email)=lower(nullif(current_setting('odu.course_owner_email',true),'')) and email_confirmed_at is not null) then raise exception 'Production owner UUID and verified email do not match'; end if;
 if not exists(select 1 from auth.users where id=v_owner) then raise exception 'Selected owner does not exist in Auth'; end if;
 -- A private import does not grant platform publication approval.
 perform pg_advisory_xact_lock(hashtextextended('odu:curated:ai-101-beginners',0));
 -- Match the existing creator RPC's per-user lock and entitlement rule.
 perform pg_advisory_xact_lock(hashtextextended(v_owner::text,0));
 if not exists(select 1 from public.learning_paths where id=v_path) then
  insert into public.user_entitlements(user_id) values(v_owner) on conflict(user_id) do nothing;
  select max_created_paths into v_limit from public.user_entitlements where user_id=v_owner for update;
  if (select count(*) from public.learning_paths where created_by=v_owner)>=v_limit then
   raise exception 'creator quota exceeded' using errcode='check_violation';
  end if;
 end if;
 insert into public.learning_paths(id,title,description,tags,created_by,visibility,wall_status,overview_markdown)
 values(v_path,'AI 101 — From Curious Beginner to Building Your First AI Application','Discover artificial intelligence through a practical seven-day learning journey. Understand AI, machine learning, neural networks, generative AI, and large language models. Learn to communicate effectively with AI tools, explore real-world applications, understand how AI systems are built, and create your first AI-powered study assistant prototype.',array['artificial-intelligence','ai-101','beginner','seven-days','machine-learning','generative-ai','large-language-models','prompt-engineering','responsible-ai']::text[],v_owner,'private','pending_review','**Artificial Intelligence · Beginner · 7 days · 7–9 hours**

**Before you start:** Basic computer literacy. No AI or programming experience required.

**Who this is for:** Students, Working professionals, Career changers, Entrepreneurs, Lifelong learners.

Approximately 45–90 minutes per day. Planned activities total 7 hours 50 minutes. Longer external courses are supporting resources; focus on the sections relevant to each day''s objective.

No programming or paid API is required. AI tools used in practice are external services, not an AI assistant built into ODU. Use non-sensitive examples and check important claims.

## What you will learn

- Explain AI, machine learning, and deep learning.
- Describe how machine learning models learn from data.
- Describe generative AI and large language models.
- Write effective prompts for AI applications.
- Identify useful AI applications and their limitations.
- Explain basic AI application architecture.
- Describe RAG and AI agents at a conceptual level.
- Build a simple prompt-based AI solution.

## Optional reference library

These references do not affect completion. Access conditions vary; no optional course subscription is required.

- [Andrew Ng — AI for Everyone](https://www.deeplearning.ai/courses/ai-for-everyone)
- [Google ML Crash Course](https://developers.google.com/machine-learning/crash-course/)
- [Hugging Face LLM Course](https://huggingface.co/learn/llm-course/chapter1/1)
- [Microsoft AI Fluency](https://learn.microsoft.com/en-us/training/paths/ai-fluency/)
- [freeCodeCamp — AI Agents for Beginners](https://www.freecodecamp.org/news/ai-agents-for-beginners/)
- [Microsoft Responsible AI](https://learn.microsoft.com/en-us/training/paths/github-responsible-ai/)

Completion records the activities you mark complete. It does not verify mastery, award a certificate, or grade your knowledge.') on conflict(id) do nothing;
 select created_by,plan_revision into v_creator,v_revision from public.learning_paths where id=v_path for update;
 if v_creator is distinct from v_owner then raise exception 'AI 101 identifier belongs to another creator; import refused'; end if;
 -- Register deterministic IDs once. The existing atomic curriculum RPC validates and updates content.
 for v_phase in select value from jsonb_array_elements(v_plan) loop
  insert into public.phases(id,path_id,title,goal,sort_order) values((v_phase->>'id')::uuid,v_path,v_phase->>'title',v_phase->>'goal',0) on conflict(id) do nothing;
  if not exists(select 1 from public.phases where id=(v_phase->>'id')::uuid and path_id=v_path) then raise exception 'Phase identifier collision'; end if;
  for v_day in select value from jsonb_array_elements(v_phase->'days') loop
   insert into public.days(id,phase_id,day_label,title,hours,sort_order) values((v_day->>'id')::uuid,(v_phase->>'id')::uuid,v_day->>'dayLabel',v_day->>'title',v_day->>'hours',0) on conflict(id) do nothing;
   if not exists(select 1 from public.days where id=(v_day->>'id')::uuid and phase_id=(v_phase->>'id')::uuid) then raise exception 'Day identifier collision'; end if;
   for v_item in select value from jsonb_array_elements(v_day->'items') loop
    insert into public.lesson_items(id,day_id,title,url,tag,sort_order) values((v_item->>'id')::uuid,(v_day->>'id')::uuid,v_item->>'title',v_item->>'url',v_item->>'tag',0) on conflict(id) do nothing;
    if not exists(select 1 from public.lesson_items where id=(v_item->>'id')::uuid and day_id=(v_day->>'id')::uuid) then raise exception 'Lesson identifier collision'; end if;
   end loop;
  end loop;
 end loop;
 v_current := public.read_learning_plan(v_path);
 if v_revision=0 or v_current->'phases' is distinct from v_plan then
  perform public.save_learning_plan(v_path,v_owner,v_plan,v_revision,false);
 end if;
 -- No memberships, progress, notes or other paths are updated by a repeat import.
 update public.learning_paths set title='AI 101 — From Curious Beginner to Building Your First AI Application',description='Discover artificial intelligence through a practical seven-day learning journey. Understand AI, machine learning, neural networks, generative AI, and large language models. Learn to communicate effectively with AI tools, explore real-world applications, understand how AI systems are built, and create your first AI-powered study assistant prototype.',tags=array['artificial-intelligence','ai-101','beginner','seven-days','machine-learning','generative-ai','large-language-models','prompt-engineering','responsible-ai']::text[],overview_markdown='**Artificial Intelligence · Beginner · 7 days · 7–9 hours**

